INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI001', 'HDSAT-RW-M20-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Boston Tea Party was an act of protest that took place on December 16, 1773, during the American Revolution. Initiated by the Sons of Liberty in Boston, the capital of Massachusetts, one of the Thirteen Colonies of British America, it escalated tensions between Great Britain and the Patriots, who opposed British policy towards its American colonies. Less than two years later, on April 19, 1775, the Battles of Lexington and Concord, also in Massachusetts, launched the eight-year American Revolutionary War, which resulted in the independence of the colonies as the United States. The source of the protestors'' anger was the passage of the Tea Act by the Parliament of Great Britain on May 10, 1773, which allowed the East India Company (EIC) to sell Chinese tea in the colonies without paying taxes apart from those imposed by the Townshend Acts. The Sons of Liberty strongly opposed both the Tea Act and Townshend Acts, which they saw as a violation of their "rights as Englishmen" to no taxation without representation. Disguised as American Indians, members of the Sons of Liberty boarded the merchantman Dartmouth on the night of December 16 after it had docked in Boston with a major shipment of EIC tea and threw 340 or 342 chests into Boston Harbor. The British government considered the protest an act of treason and responded with several punitive measures.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Boston Tea Party was a celebration of the East India Company''s trade in the colonies."}, {"id": "B", "text": "The protest ended British rule in Massachusetts almost immediately."}, {"id": "C", "text": "The Tea Act was repealed after the colonists destroyed the tea."}, {"id": "D", "text": "A 1773 protest against British tea policy escalated colonial tensions and preceded the Revolutionary War."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Boston Tea Party", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Boston_Tea_Party', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI001', 'D', ARRAY['D']::TEXT[], 'The passage presents the tea destruction as a protest over taxation, explains the grievance behind it, and connects it to the escalation that led to war.', '{"A": "The text describes the event as an act of protest against the Tea Act and Townshend Acts.", "B": "The text says the protest escalated tensions and that war began less than two years later.", "C": "The text says the British government responded with punitive measures, not repeal."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF001', 'HDSAT-RW-M20-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Boston Tea Party was an act of protest that took place on December 16, 1773, during the American Revolution. Initiated by the Sons of Liberty in Boston, the capital of Massachusetts, one of the Thirteen Colonies of British America, it escalated tensions between Great Britain and the Patriots, who opposed British policy towards its American colonies. Less than two years later, on April 19, 1775, the Battles of Lexington and Concord, also in Massachusetts, launched the eight-year American Revolutionary War, which resulted in the independence of the colonies as the United States. The source of the protestors'' anger was the passage of the Tea Act by the Parliament of Great Britain on May 10, 1773, which allowed the East India Company (EIC) to sell Chinese tea in the colonies without paying taxes apart from those imposed by the Townshend Acts. The Sons of Liberty strongly opposed both the Tea Act and Townshend Acts, which they saw as a violation of their "rights as Englishmen" to no taxation without representation. Disguised as American Indians, members of the Sons of Liberty boarded the merchantman Dartmouth on the night of December 16 after it had docked in Boston with a major shipment of EIC tea and threw 340 or 342 chests into Boston Harbor. The British government considered the protest an act of treason and responded with several punitive measures.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF001', 'C', ARRAY['C']::TEXT[], 'The final sentence states that the British government viewed the protest as treason and answered it with punitive measures, so punishment is the logical completion.', '{"B": "The text states that the government responded with several punitive measures.", "A": "The government treated the event as treason, so a reward is contrary to the text.", "D": "The text does not say representation was offered; it says the colonists demanded it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS001', 'HDSAT-RW-M20-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Boston Tea Party was an act of protest that took place on December 16, 1773, during the American Revolution. Initiated by the Sons of Liberty in Boston, the capital of Massachusetts, one of the Thirteen Colonies of British America, it escalated tensions between Great Britain and the Patriots, who opposed British policy towards its American colonies. Less than two years later, on April 19, 1775, the Battles of Lexington and Concord, also in Massachusetts, launched the eight-year American Revolutionary War, which resulted in the independence of the colonies as the United States. The source of the protestors'' anger was the passage of the Tea Act by the Parliament of Great Britain on May 10, 1773, which allowed the East India Company (EIC) to sell Chinese tea in the colonies without paying taxes apart from those imposed by the Townshend Acts. The Sons of Liberty strongly opposed both the Tea Act and Townshend Acts, which they saw as a violation of their "rights as Englishmen" to no taxation without representation. Disguised as American Indians, members of the Sons of Liberty boarded the merchantman Dartmouth on the night of December 16 after it had docked in Boston with a major shipment of EIC tea and threw 340 or 342 chests into Boston Harbor. The British government considered the protest an act of treason and responded with several punitive measures.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares the tea trade in Boston with the tea trade in China."}, {"id": "B", "text": "It lists the members of the Sons of Liberty and their occupations."}, {"id": "C", "text": "It narrates the protest, explains the grievance that prompted it, and notes the British response."}, {"id": "D", "text": "It argues that the Revolutionary War could have been avoided."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Boston Tea Party", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Boston_Tea_Party', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS001', 'C', ARRAY['C']::TEXT[], 'The passage is organized chronologically around the event, its cause, and its consequences.', '{"A": "The text moves from the event to the Tea Act and colonial objections, then to the government''s reaction.", "B": "China is mentioned only as the source of the tea.", "D": "No individual members are named or described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE001', 'HDSAT-RW-M20-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Boston Tea Party was an act of protest that took place on December 16, 1773, during the American Revolution. Initiated by the Sons of Liberty in Boston, the capital of Massachusetts, one of the Thirteen Colonies of British America, it escalated tensions between Great Britain and the Patriots, who opposed British policy towards its American colonies. Less than two years later, on April 19, 1775, the Battles of Lexington and Concord, also in Massachusetts, launched the eight-year American Revolutionary War, which resulted in the independence of the colonies as the United States. The source of the protestors'' anger was the passage of the Tea Act by the Parliament of Great Britain on May 10, 1773, which allowed the East India Company (EIC) to sell Chinese tea in the colonies without paying taxes apart from those imposed by the Townshend Acts. The Sons of Liberty strongly opposed both the Tea Act and Townshend Acts, which they saw as a violation of their "rights as Englishmen" to no taxation without representation. Disguised as American Indians, members of the Sons of Liberty boarded the merchantman Dartmouth on the night of December 16 after it had docked in Boston with a major shipment of EIC tea and threw 340 or 342 chests into Boston Harbor. The British government considered the protest an act of treason and responded with several punitive measures.', 'Which quotation from the text most directly supports the claim that the protest involved a coordinated destruction of private property?', '[{"id": "A", "text": "The British government considered the protest an act of treason and responded with several punitive measures."}, {"id": "B", "text": "Disguised as American Indians, members of the Sons of Liberty boarded the merchantman Dartmouth on the night of December 16 after it had docked in Boston with a major shipment of EIC tea and threw 340 or 342 chests into Boston Harbor."}, {"id": "C", "text": "The source of the protestors'' anger was the passage of the Tea Act by the Parliament of Great Britain on May 10, 1773."}, {"id": "D", "text": "The Boston Tea Party was an act of protest that took place on December 16, 1773, during the American Revolution."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Boston Tea Party", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Boston_Tea_Party', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE001', 'B', ARRAY['B']::TEXT[], 'Only the correct quotation reports disguised participants boarding a ship and throwing hundreds of chests of tea into the harbor.', '{"D": "This sentence describes the planning and the destruction but not the number of chests.", "C": "This sentence explains the grievance rather than the action.", "A": "This sentence describes the response to the protest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI002', 'HDSAT-RW-M20-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Haitian Revolution, also known as the Haitian War of Independence, was an armed conflict and insurrection by enslaved Black Africans against French colonial rule in Saint-Domingue, now the sovereign state of Haiti. The revolution is one of the only known slave rebellions in human history that led to the founding of a state which was both free from slavery (though not from forced labour) and ruled by former enslaved captives. Vincent Ogé''s 1790 revolt by free Mulattoes (of mixed French European and Black African ancestry) pressured the French Revolutionary government to grant them citizenship in May 1791, leading to further clashes with slave owners that had destabilized Saint-Domingue and led to the slave revolt on 21 August 1791, which ended with the former colony''s independence on 1 January 1804, with the ex-slave Toussaint Louverture emerging as its most prominent general. The successful revolution was a defining moment in the history of the Atlantic World and the revolution''s effects on the institution of slavery were felt throughout the Americas. The end of French rule and the abolition of slavery in the former colony was followed by a successful defense of the freedoms the former Black slaves had won with the collaboration with already free people of color, of their independence from Europeans. The revolution, the largest slave uprising since Spartacus''s unsuccessful revolt against the Roman Republic nearly 1,900 years earlier, shocked the Western world.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A slave uprising in Saint-Domingue became a revolution that founded a state ruled by formerly enslaved people and unsettled slaveholding societies."}, {"id": "B", "text": "The Haitian Revolution was a minor revolt that left French rule intact."}, {"id": "C", "text": "The revolution was led by free European colonists seeking independence from France."}, {"id": "D", "text": "The revolution ended slavery throughout the Americas at once."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Haitian Revolution", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Haitian_Revolution', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI002', 'A', ARRAY['A']::TEXT[], 'The passage emphasizes the revolution''s origins in slave insurrection, its rare success in founding a free state, and its wide impact.', '{"B": "The text says the revolution ended French rule and produced independence in 1804.", "C": "The text describes an insurrection by enslaved Black Africans against French colonial rule.", "D": "The text says its effects were felt throughout the Americas, not that slavery ended everywhere immediately."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF002', 'HDSAT-RW-M20-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The Haitian Revolution, also known as the Haitian War of Independence, was an armed conflict and insurrection by enslaved Black Africans against French colonial rule in Saint-Domingue, now the sovereign state of Haiti. The revolution is one of the only known slave rebellions in human history that led to the founding of a state which was both free from slavery (though not from forced labour) and ruled by former enslaved captives. Vincent Ogé''s 1790 revolt by free Mulattoes (of mixed French European and Black African ancestry) pressured the French Revolutionary government to grant them citizenship in May 1791, leading to further clashes with slave owners that had destabilized Saint-Domingue and led to the slave revolt on 21 August 1791, which ended with the former colony''s independence on 1 January 1804, with the ex-slave Toussaint Louverture emerging as its most prominent general. The successful revolution was a defining moment in the history of the Atlantic World and the revolution''s effects on the institution of slavery were felt throughout the Americas. The end of French rule and the abolition of slavery in the former colony was followed by a successful defense of the freedoms the former Black slaves had won with the collaboration with already free people of color, of their independence from Europeans. The revolution, the largest slave uprising since Spartacus''s unsuccessful revolt against the Roman Republic nearly 1,900 years earlier, shocked the Western world.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF002', 'D', ARRAY['D']::TEXT[], 'A successful slave revolution that ended French rule would plausibly alarm slaveholders, which is why its effects were felt across the Americas.', '{"B": "The text says the revolution shocked the Western world and its effects were felt throughout the Americas.", "C": "Slaveholders would not welcome a successful rebellion that ended slavery.", "A": "The text does not discuss profitability."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS002', 'HDSAT-RW-M20-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Haitian Revolution, also known as the Haitian War of Independence, was an armed conflict and insurrection by enslaved Black Africans against French colonial rule in Saint-Domingue, now the sovereign state of Haiti. The revolution is one of the only known slave rebellions in human history that led to the founding of a state which was both free from slavery (though not from forced labour) and ruled by former enslaved captives. Vincent Ogé''s 1790 revolt by free Mulattoes (of mixed French European and Black African ancestry) pressured the French Revolutionary government to grant them citizenship in May 1791, leading to further clashes with slave owners that had destabilized Saint-Domingue and led to the slave revolt on 21 August 1791, which ended with the former colony''s independence on 1 January 1804, with the ex-slave Toussaint Louverture emerging as its most prominent general. The successful revolution was a defining moment in the history of the Atlantic World and the revolution''s effects on the institution of slavery were felt throughout the Americas. The end of French rule and the abolition of slavery in the former colony was followed by a successful defense of the freedoms the former Black slaves had won with the collaboration with already free people of color, of their independence from Europeans. The revolution, the largest slave uprising since Spartacus''s unsuccessful revolt against the Roman Republic nearly 1,900 years earlier, shocked the Western world.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the daily life of enslaved workers on a plantation."}, {"id": "B", "text": "It identifies the revolution, traces its course to independence, and assesses its historical significance."}, {"id": "C", "text": "It explains the economic theory behind colonial trade."}, {"id": "D", "text": "It compares the Haitian Revolution with the American Revolution in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Haitian Revolution", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Haitian_Revolution', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS002', 'B', ARRAY['B']::TEXT[], 'The passage introduces the conflict, summarizes its chronology, and closes with its significance for the Atlantic world.', '{"D": "The text moves from the insurrection to independence and then to its impact.", "A": "The American Revolution is not discussed.", "C": "Daily plantation life is not described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE002', 'HDSAT-RW-M20-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Haitian Revolution, also known as the Haitian War of Independence, was an armed conflict and insurrection by enslaved Black Africans against French colonial rule in Saint-Domingue, now the sovereign state of Haiti. The revolution is one of the only known slave rebellions in human history that led to the founding of a state which was both free from slavery (though not from forced labour) and ruled by former enslaved captives. Vincent Ogé''s 1790 revolt by free Mulattoes (of mixed French European and Black African ancestry) pressured the French Revolutionary government to grant them citizenship in May 1791, leading to further clashes with slave owners that had destabilized Saint-Domingue and led to the slave revolt on 21 August 1791, which ended with the former colony''s independence on 1 January 1804, with the ex-slave Toussaint Louverture emerging as its most prominent general. The successful revolution was a defining moment in the history of the Atlantic World and the revolution''s effects on the institution of slavery were felt throughout the Americas. The end of French rule and the abolition of slavery in the former colony was followed by a successful defense of the freedoms the former Black slaves had won with the collaboration with already free people of color, of their independence from Europeans. The revolution, the largest slave uprising since Spartacus''s unsuccessful revolt against the Roman Republic nearly 1,900 years earlier, shocked the Western world.', 'Which quotation from the text most directly supports the claim that the revolution produced a government led by formerly enslaved people?', '[{"id": "A", "text": "Vincent Ogé''s 1790 revolt by free Mulattoes pressured the French Revolutionary government to grant them citizenship in May 1791."}, {"id": "B", "text": "The successful revolution was a defining moment in the history of the Atlantic World."}, {"id": "C", "text": "The revolution, the largest slave uprising since Spartacus''s unsuccessful revolt against the Roman Republic nearly 1,900 years earlier, shocked the Western world."}, {"id": "D", "text": "The revolution is one of the only known slave rebellions in human history that led to the founding of a state which was both free from slavery (though not from forced labour) and ruled by former enslaved captives."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Haitian Revolution", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Haitian_Revolution', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE002', 'D', ARRAY['D']::TEXT[], 'The correct quotation explicitly says the resulting state was ruled by former enslaved captives.', '{"C": "This sentence describes the scale and impact of the uprising.", "A": "This sentence concerns free people of color and citizenship.", "B": "This sentence assesses the revolution''s importance without naming its rulers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI003', 'HDSAT-RW-M20-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Women''s suffrage is the right of women to vote in elections. Historically, women rarely had the right to vote, even in ostensibly democratic systems of government. The 19th century saw many movements advocating "universal [male] suffrage", most notably in Europe and North America; following this, movements for women''s suffrage became prominent, and between the late 19th century and the early 20th century, women''s suffrage was accomplished in Australasia, then Europe, and then the Americas. By the middle of the 20th century, women''s suffrage had been established as a norm of democratic governance. Extended political campaigns by women and their male supporters played a central role in changing public attitudes, altering norms, and achieving legislation or constitutional amendments for women''s suffrage. The first wave of women''s suffrage took place in 1893–1930, covering English-speaking countries, Scandinavian states, and some other parts of Europe. The experience of the First World War has been characterized as an important factor in shifting public support for women''s suffrage. The second wave, 1930–1970, covered nearly all Latin-American countries, much of Sub-Saharan Africa and some European laggards (France, Spain, Belgium). Prior to 1893, there were instances where women could vote in some elections and at the subnational level. The first national granting of women''s suffrage was in 1893 in the then self-governing British colony of New Zealand.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Only women in Europe campaigned for the right to vote."}, {"id": "B", "text": "Women''s suffrage was granted mainly to reward wartime service."}, {"id": "C", "text": "Women gained the vote in every country at the same time."}, {"id": "D", "text": "Women''s suffrage spread through sustained campaigns and became a democratic norm, first nationally in New Zealand."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Women''s suffrage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Women%27s_suffrage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI003', 'D', ARRAY['D']::TEXT[], 'The passage defines suffrage, credits extended campaigns with changing attitudes, and traces its spread by region and period.', '{"C": "The text describes two waves and different regional timelines.", "B": "The First World War is called a factor in shifting support, not the sole cause.", "A": "The text describes campaigns in Europe, North America, Australasia, and elsewhere."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF003', 'HDSAT-RW-M20-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Women''s suffrage is the right of women to vote in elections. Historically, women rarely had the right to vote, even in ostensibly democratic systems of government. The 19th century saw many movements advocating "universal [male] suffrage", most notably in Europe and North America; following this, movements for women''s suffrage became prominent, and between the late 19th century and the early 20th century, women''s suffrage was accomplished in Australasia, then Europe, and then the Americas. By the middle of the 20th century, women''s suffrage had been established as a norm of democratic governance. Extended political campaigns by women and their male supporters played a central role in changing public attitudes, altering norms, and achieving legislation or constitutional amendments for women''s suffrage. The first wave of women''s suffrage took place in 1893–1930, covering English-speaking countries, Scandinavian states, and some other parts of Europe. The experience of the First World War has been characterized as an important factor in shifting public support for women''s suffrage. The second wave, 1930–1970, covered nearly all Latin-American countries, much of Sub-Saharan Africa and some European laggards (France, Spain, Belgium). Prior to 1893, there were instances where women could vote in some elections and at the subnational level. The first national granting of women''s suffrage was in 1893 in the then self-governing British colony of New Zealand.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF003', 'B', ARRAY['B']::TEXT[], 'If wartime experience shifted public support toward suffrage, that shift would plausibly help produce legislation or constitutional amendments.', '{"D": "The text links the war''s experience to shifting public support for suffrage.", "C": "The text says the first wave ran through 1930, so campaigns did not end.", "A": "Nothing in the text suggests women abandoned the cause."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS003', 'HDSAT-RW-M20-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Women''s suffrage is the right of women to vote in elections. Historically, women rarely had the right to vote, even in ostensibly democratic systems of government. The 19th century saw many movements advocating "universal [male] suffrage", most notably in Europe and North America; following this, movements for women''s suffrage became prominent, and between the late 19th century and the early 20th century, women''s suffrage was accomplished in Australasia, then Europe, and then the Americas. By the middle of the 20th century, women''s suffrage had been established as a norm of democratic governance. Extended political campaigns by women and their male supporters played a central role in changing public attitudes, altering norms, and achieving legislation or constitutional amendments for women''s suffrage. The first wave of women''s suffrage took place in 1893–1930, covering English-speaking countries, Scandinavian states, and some other parts of Europe. The experience of the First World War has been characterized as an important factor in shifting public support for women''s suffrage. The second wave, 1930–1970, covered nearly all Latin-American countries, much of Sub-Saharan Africa and some European laggards (France, Spain, Belgium). Prior to 1893, there were instances where women could vote in some elections and at the subnational level. The first national granting of women''s suffrage was in 1893 in the then self-governing British colony of New Zealand.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that suffrage had no effect on democratic governance."}, {"id": "B", "text": "It compares voting systems in New Zealand and France in detail."}, {"id": "C", "text": "It defines women''s suffrage and then traces its achievement in successive regional waves."}, {"id": "D", "text": "It profiles individual suffragists and their biographies."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Women''s suffrage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Women%27s_suffrage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS003', 'C', ARRAY['C']::TEXT[], 'The passage opens with a definition and proceeds chronologically through two waves of enfranchisement.', '{"D": "The text defines the right, then describes the first and second waves.", "B": "No individual campaigner is named.", "A": "France is mentioned only as a late adopter."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE003', 'HDSAT-RW-M20-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Women''s suffrage is the right of women to vote in elections. Historically, women rarely had the right to vote, even in ostensibly democratic systems of government. The 19th century saw many movements advocating "universal [male] suffrage", most notably in Europe and North America; following this, movements for women''s suffrage became prominent, and between the late 19th century and the early 20th century, women''s suffrage was accomplished in Australasia, then Europe, and then the Americas. By the middle of the 20th century, women''s suffrage had been established as a norm of democratic governance. Extended political campaigns by women and their male supporters played a central role in changing public attitudes, altering norms, and achieving legislation or constitutional amendments for women''s suffrage. The first wave of women''s suffrage took place in 1893–1930, covering English-speaking countries, Scandinavian states, and some other parts of Europe. The experience of the First World War has been characterized as an important factor in shifting public support for women''s suffrage. The second wave, 1930–1970, covered nearly all Latin-American countries, much of Sub-Saharan Africa and some European laggards (France, Spain, Belgium). Prior to 1893, there were instances where women could vote in some elections and at the subnational level. The first national granting of women''s suffrage was in 1893 in the then self-governing British colony of New Zealand.', 'Which quotation from the text most directly supports the claim that organized campaigning changed public opinion?', '[{"id": "A", "text": "By the middle of the 20th century, women''s suffrage had been established as a norm of democratic governance."}, {"id": "B", "text": "Extended political campaigns by women and their male supporters played a central role in changing public attitudes, altering norms, and achieving legislation or constitutional amendments for women''s suffrage."}, {"id": "C", "text": "The first national granting of women''s suffrage was in 1893 in the then self-governing British colony of New Zealand."}, {"id": "D", "text": "Women''s suffrage is the right of women to vote in elections."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Women''s suffrage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Women%27s_suffrage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE003', 'B', ARRAY['B']::TEXT[], 'The correct quotation explicitly credits extended campaigns with changing attitudes and norms.', '{"D": "This sentence defines the term.", "C": "This sentence records a date and place.", "A": "This sentence describes the outcome by mid-century."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI004', 'HDSAT-RW-M20-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Marshall Plan (officially the European Recovery Program, ERP) was an American initiative enacted in 1948 to provide foreign aid to Western Europe. The United States transferred US$13.3 billion to 17 European countries (equivalent to $141 billion in 2025) in economic recovery programs to Western European economies after the end of World War II in Europe. Replacing an earlier proposal for a Morgenthau Plan, it operated for four years beginning on April 3, 1948; though in 1951, the Marshall Plan was largely replaced by the Mutual Security Act. The goals of the United States were to rebuild war-torn regions, remove trade barriers, modernize industry, improve European prosperity and prevent the spread of communism. The Marshall Plan proposed the reduction of interstate barriers and the economic integration of the European continent while also encouraging an increase in productivity as well as the adoption of modern business procedures. According to a report from the U.S. Congressional Research Service, 83% of the Marshall Plan funds were spent within the United States. The Marshall Plan aid was divided among the participating states roughly on a per capital basis. A larger amount was given to the major industrial powers, as the prevailing opinion was that their resuscitation was essential for the general European revival. Somewhat more aid per capital was also directed toward the Allied nations, with less for those that had been part of the Axis or remained neutral.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Marshall Plan was a military alliance formed to defend Western Europe."}, {"id": "B", "text": "The Marshall Plan sent large-scale American aid to Western Europe to rebuild economies and resist communism."}, {"id": "C", "text": "The plan required European countries to adopt American laws."}, {"id": "D", "text": "The plan ended immediately after the war in 1945."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Marshall Plan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Marshall_Plan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI004', 'B', ARRAY['B']::TEXT[], 'The passage describes the aid program, its scale, its goals, and how the money was distributed.', '{"A": "The text describes foreign aid for economic recovery, not a military alliance.", "C": "The text mentions trade barriers and business procedures, not legal systems.", "D": "The text says the program began in 1948 and operated for four years."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF004', 'HDSAT-RW-M20-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The Marshall Plan (officially the European Recovery Program, ERP) was an American initiative enacted in 1948 to provide foreign aid to Western Europe. The United States transferred US$13.3 billion to 17 European countries (equivalent to $141 billion in 2025) in economic recovery programs to Western European economies after the end of World War II in Europe. Replacing an earlier proposal for a Morgenthau Plan, it operated for four years beginning on April 3, 1948; though in 1951, the Marshall Plan was largely replaced by the Mutual Security Act. The goals of the United States were to rebuild war-torn regions, remove trade barriers, modernize industry, improve European prosperity and prevent the spread of communism. The Marshall Plan proposed the reduction of interstate barriers and the economic integration of the European continent while also encouraging an increase in productivity as well as the adoption of modern business procedures. According to a report from the U.S. Congressional Research Service, 83% of the Marshall Plan funds were spent within the United States. The Marshall Plan aid was divided among the participating states roughly on a per capital basis. A larger amount was given to the major industrial powers, as the prevailing opinion was that their resuscitation was essential for the general European revival. Somewhat more aid per capital was also directed toward the Allied nations, with less for those that had been part of the Axis or remained neutral.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF004', 'C', ARRAY['C']::TEXT[], 'Aid money spent inside the United States would have purchased American goods and services, benefiting domestic suppliers.', '{"D": "The text says funds were spent in the United States, which implies purchases from American firms.", "A": "The text says the United States transferred $13.3 billion to 17 European countries.", "B": "Spending on American goods would support, not reduce, production."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS004', 'HDSAT-RW-M20-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Marshall Plan (officially the European Recovery Program, ERP) was an American initiative enacted in 1948 to provide foreign aid to Western Europe. The United States transferred US$13.3 billion to 17 European countries (equivalent to $141 billion in 2025) in economic recovery programs to Western European economies after the end of World War II in Europe. Replacing an earlier proposal for a Morgenthau Plan, it operated for four years beginning on April 3, 1948; though in 1951, the Marshall Plan was largely replaced by the Mutual Security Act. The goals of the United States were to rebuild war-torn regions, remove trade barriers, modernize industry, improve European prosperity and prevent the spread of communism. The Marshall Plan proposed the reduction of interstate barriers and the economic integration of the European continent while also encouraging an increase in productivity as well as the adoption of modern business procedures. According to a report from the U.S. Congressional Research Service, 83% of the Marshall Plan funds were spent within the United States. The Marshall Plan aid was divided among the participating states roughly on a per capital basis. A larger amount was given to the major industrial powers, as the prevailing opinion was that their resuscitation was essential for the general European revival. Somewhat more aid per capital was also directed toward the Allied nations, with less for those that had been part of the Axis or remained neutral.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It introduces the program, states its goals, and explains how aid was divided."}, {"id": "B", "text": "It argues that the plan caused the Cold War."}, {"id": "C", "text": "It narrates the military campaigns of the Second World War."}, {"id": "D", "text": "It compares the Marshall Plan with the Marshall Court."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Marshall Plan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Marshall_Plan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS004', 'A', ARRAY['A']::TEXT[], 'The passage moves from the program''s identity and scale to its objectives and then to the allocation of aid.', '{"C": "The text describes the aid program and its distribution, not battles.", "D": "The Marshall Court is not mentioned.", "B": "The text presents the plan as a response to postwar conditions, including communism."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE004', 'HDSAT-RW-M20-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Marshall Plan (officially the European Recovery Program, ERP) was an American initiative enacted in 1948 to provide foreign aid to Western Europe. The United States transferred US$13.3 billion to 17 European countries (equivalent to $141 billion in 2025) in economic recovery programs to Western European economies after the end of World War II in Europe. Replacing an earlier proposal for a Morgenthau Plan, it operated for four years beginning on April 3, 1948; though in 1951, the Marshall Plan was largely replaced by the Mutual Security Act. The goals of the United States were to rebuild war-torn regions, remove trade barriers, modernize industry, improve European prosperity and prevent the spread of communism. The Marshall Plan proposed the reduction of interstate barriers and the economic integration of the European continent while also encouraging an increase in productivity as well as the adoption of modern business procedures. According to a report from the U.S. Congressional Research Service, 83% of the Marshall Plan funds were spent within the United States. The Marshall Plan aid was divided among the participating states roughly on a per capital basis. A larger amount was given to the major industrial powers, as the prevailing opinion was that their resuscitation was essential for the general European revival. Somewhat more aid per capital was also directed toward the Allied nations, with less for those that had been part of the Axis or remained neutral.', 'Which quotation from the text most directly supports the claim that the aid had political as well as economic aims?', '[{"id": "A", "text": "It operated for four years beginning on April 3, 1948."}, {"id": "B", "text": "The Marshall Plan aid was divided among the participating states roughly on a per capital basis."}, {"id": "C", "text": "The Marshall Plan (officially the European Recovery Program, ERP) was an American initiative enacted in 1948 to provide foreign aid to Western Europe."}, {"id": "D", "text": "The goals of the United States were to rebuild war-torn regions, remove trade barriers, modernize industry, improve European prosperity and prevent the spread of communism."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Marshall Plan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Marshall_Plan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE004', 'D', ARRAY['D']::TEXT[], 'The correct quotation names preventing the spread of communism alongside economic goals.', '{"C": "This sentence identifies the program and its general purpose.", "A": "This sentence gives the program''s duration.", "B": "This sentence describes how aid was allocated."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI005', 'HDSAT-RW-M20-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Berlin Blockade (24 June 1948 – 12 May 1949) was one of the first major international crises of the Cold War. During the multinational occupation of post–World War II Germany, the Soviet Union blocked the Western Allies'' railway, road, and canal access to the sectors of Berlin under Western control. The Soviets offered to drop the blockade if the Western Allies withdrew the newly introduced Deutsche Mark from West Berlin. The Western Allies organised the Berlin Airlift (German: Berliner Luftbrücke, lit. "Berlin Air Bridge") from 26 June 1948 to 30 September 1949 to carry supplies to the people of West Berlin, a difficult feat given the size of the city and the population. American and British air forces landed in Berlin more than 200,000 times, delivering 13,000 tons of food, fuel, and other necessities each day. Among these was the work of the later concurrent Operation Little Vittles in which candy-dropping aircraft dubbed "raisin bombers" generated much goodwill among German children. On 12 May 1949, the USSR lifted the blockade of West Berlin, due to economic issues in East Berlin, although for a time the Americans and British continued to supply the city by air as they were worried that the Soviets would resume the blockade and were only trying to disrupt Western supply lines. The Berlin Airlift officially ended on 30 September 1949 after fifteen months.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Western Allies abandoned West Berlin after the Soviet Union blocked its roads."}, {"id": "B", "text": "The Soviet Union successfully forced the Western Allies out of Berlin."}, {"id": "C", "text": "The blockade began after the Berlin Airlift ended in 1949."}, {"id": "D", "text": "The Soviet blockade of West Berlin was countered by a massive Western airlift that kept the city supplied until the blockade ended."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Berlin Blockade", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Berlin_Blockade', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI005', 'D', ARRAY['D']::TEXT[], 'The passage centers on the blockade and the airlift that defeated its purpose.', '{"A": "The text describes the airlift that carried supplies to West Berlin.", "C": "The text says the airlift began two days after the blockade started.", "B": "The text says the USSR lifted the blockade in May 1949."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF005', 'HDSAT-RW-M20-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The Berlin Blockade (24 June 1948 – 12 May 1949) was one of the first major international crises of the Cold War. During the multinational occupation of post–World War II Germany, the Soviet Union blocked the Western Allies'' railway, road, and canal access to the sectors of Berlin under Western control. The Soviets offered to drop the blockade if the Western Allies withdrew the newly introduced Deutsche Mark from West Berlin. The Western Allies organised the Berlin Airlift (German: Berliner Luftbrücke, lit. "Berlin Air Bridge") from 26 June 1948 to 30 September 1949 to carry supplies to the people of West Berlin, a difficult feat given the size of the city and the population. American and British air forces landed in Berlin more than 200,000 times, delivering 13,000 tons of food, fuel, and other necessities each day. Among these was the work of the later concurrent Operation Little Vittles in which candy-dropping aircraft dubbed "raisin bombers" generated much goodwill among German children. On 12 May 1949, the USSR lifted the blockade of West Berlin, due to economic issues in East Berlin, although for a time the Americans and British continued to supply the city by air as they were worried that the Soviets would resume the blockade and were only trying to disrupt Western supply lines. The Berlin Airlift officially ended on 30 September 1949 after fifteen months.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF005', 'B', ARRAY['B']::TEXT[], 'The daily tonnage and landing counts show how the airlift kept West Berlin supplied during the blockade.', '{"D": "The figures describe the scale needed to supply the city during the blockade.", "A": "The text does not say air transport replaced ground transport afterward.", "C": "The text calls the blockade one of the first major crises of the Cold War, which continued."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS005', 'HDSAT-RW-M20-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Berlin Blockade (24 June 1948 – 12 May 1949) was one of the first major international crises of the Cold War. During the multinational occupation of post–World War II Germany, the Soviet Union blocked the Western Allies'' railway, road, and canal access to the sectors of Berlin under Western control. The Soviets offered to drop the blockade if the Western Allies withdrew the newly introduced Deutsche Mark from West Berlin. The Western Allies organised the Berlin Airlift (German: Berliner Luftbrücke, lit. "Berlin Air Bridge") from 26 June 1948 to 30 September 1949 to carry supplies to the people of West Berlin, a difficult feat given the size of the city and the population. American and British air forces landed in Berlin more than 200,000 times, delivering 13,000 tons of food, fuel, and other necessities each day. Among these was the work of the later concurrent Operation Little Vittles in which candy-dropping aircraft dubbed "raisin bombers" generated much goodwill among German children. On 12 May 1949, the USSR lifted the blockade of West Berlin, due to economic issues in East Berlin, although for a time the Americans and British continued to supply the city by air as they were worried that the Soviets would resume the blockade and were only trying to disrupt Western supply lines. The Berlin Airlift officially ended on 30 September 1949 after fifteen months.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains the causes of the First World War."}, {"id": "B", "text": "It compares Soviet and American aircraft designs."}, {"id": "C", "text": "It profiles the pilots who flew the airlift."}, {"id": "D", "text": "It describes the blockade, the airlift organized in response, and the blockade''s end."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Berlin Blockade", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Berlin_Blockade', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS005', 'D', ARRAY['D']::TEXT[], 'The passage is a chronological account of the crisis and the response.', '{"B": "The text follows the crisis from blockade to airlift to the lifting of the blockade.", "A": "Aircraft designs are not discussed.", "C": "The First World War is mentioned only in the phrase post-World War II."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE005', 'HDSAT-RW-M20-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Berlin Blockade (24 June 1948 – 12 May 1949) was one of the first major international crises of the Cold War. During the multinational occupation of post–World War II Germany, the Soviet Union blocked the Western Allies'' railway, road, and canal access to the sectors of Berlin under Western control. The Soviets offered to drop the blockade if the Western Allies withdrew the newly introduced Deutsche Mark from West Berlin. The Western Allies organised the Berlin Airlift (German: Berliner Luftbrücke, lit. "Berlin Air Bridge") from 26 June 1948 to 30 September 1949 to carry supplies to the people of West Berlin, a difficult feat given the size of the city and the population. American and British air forces landed in Berlin more than 200,000 times, delivering 13,000 tons of food, fuel, and other necessities each day. Among these was the work of the later concurrent Operation Little Vittles in which candy-dropping aircraft dubbed "raisin bombers" generated much goodwill among German children. On 12 May 1949, the USSR lifted the blockade of West Berlin, due to economic issues in East Berlin, although for a time the Americans and British continued to supply the city by air as they were worried that the Soviets would resume the blockade and were only trying to disrupt Western supply lines. The Berlin Airlift officially ended on 30 September 1949 after fifteen months.', 'Which quotation from the text most directly supports the claim that the airlift operated on an enormous scale?', '[{"id": "A", "text": "On 12 May 1949, the USSR lifted the blockade of West Berlin, due to economic issues in East Berlin."}, {"id": "B", "text": "The Berlin Blockade (24 June 1948 - 12 May 1949) was one of the first major international crises of the Cold War."}, {"id": "C", "text": "American and British air forces landed in Berlin more than 200,000 times, delivering 13,000 tons of food, fuel, and other necessities each day."}, {"id": "D", "text": "The Soviets offered to drop the blockade if the Western Allies withdrew the newly introduced Deutsche Mark from West Berlin."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Berlin Blockade", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Berlin_Blockade', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE005', 'C', ARRAY['C']::TEXT[], 'Only the correct quotation gives the landing count and daily tonnage that demonstrate the airlift''s scale.', '{"B": "This sentence dates the crisis and places it in the Cold War.", "D": "This sentence describes a Soviet condition for ending the blockade.", "A": "This sentence reports the end of the blockade."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI006', 'HDSAT-RW-M20-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Magna Carta (Medieval Latin for "Great Charter"), sometimes spelled Magna Charta, is a royal charter of rights sealed by King John of England at Runnymede, near Windsor, on 15 June 1215. First drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons who demanded that the King confirm the Charter of Liberties, it promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown, to be implemented through a council of 25 barons. Neither side stood by their commitments, and the charter was annulled by Pope Innocent III, leading to the First Barons'' War. After John''s death, the regency government of his young son, Henry III, reissued the document in 1216, stripped of some of its more radical content, in an unsuccessful bid to build political support for their cause. At the end of the war in 1217, it formed part of the peace treaty agreed at Lambeth, where the document acquired the name "Magna Carta", to distinguish it from the smaller Charter of the Forest, which was issued at the same time. Short of funds, Henry reissued the charter again in 1225 in exchange for a grant of new taxes. His son, Edward I, repeated the exercise in 1297, this time confirming it as part of England''s statute law.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The charter was immediately accepted by both sides and never revised."}, {"id": "B", "text": "Magna Carta began as a peace deal limiting royal power, failed at first, and was reissued until it became statute law."}, {"id": "C", "text": "Magna Carta was written by King John alone to increase his authority."}, {"id": "D", "text": "Magna Carta established a permanent parliament in 1215."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Magna Carta", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Magna_Carta', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI006', 'B', ARRAY['B']::TEXT[], 'The passage covers the charter''s origin, its guarantees, its failure, and its later reissues.', '{"C": "The text says it was drafted by Archbishop Langton to make peace with rebel barons.", "A": "The text says neither side stood by its commitments and the charter was annulled.", "D": "The text describes a council of 25 barons, not a parliament."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF006', 'HDSAT-RW-M20-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Magna Carta (Medieval Latin for "Great Charter"), sometimes spelled Magna Charta, is a royal charter of rights sealed by King John of England at Runnymede, near Windsor, on 15 June 1215. First drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons who demanded that the King confirm the Charter of Liberties, it promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown, to be implemented through a council of 25 barons. Neither side stood by their commitments, and the charter was annulled by Pope Innocent III, leading to the First Barons'' War. After John''s death, the regency government of his young son, Henry III, reissued the document in 1216, stripped of some of its more radical content, in an unsuccessful bid to build political support for their cause. At the end of the war in 1217, it formed part of the peace treaty agreed at Lambeth, where the document acquired the name "Magna Carta", to distinguish it from the smaller Charter of the Forest, which was issued at the same time. Short of funds, Henry reissued the charter again in 1225 in exchange for a grant of new taxes. His son, Edward I, repeated the exercise in 1297, this time confirming it as part of England''s statute law.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF006', 'B', ARRAY['B']::TEXT[], 'The annulment and the First Barons'' War show that the dispute continued rather than being settled.', '{"C": "The text says the failure led to the First Barons'' War.", "A": "The text says the annulment led to war, not peace.", "D": "The text says the charter limited feudal payments, not that it abolished the monarchy."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS006', 'HDSAT-RW-M20-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Magna Carta (Medieval Latin for "Great Charter"), sometimes spelled Magna Charta, is a royal charter of rights sealed by King John of England at Runnymede, near Windsor, on 15 June 1215. First drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons who demanded that the King confirm the Charter of Liberties, it promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown, to be implemented through a council of 25 barons. Neither side stood by their commitments, and the charter was annulled by Pope Innocent III, leading to the First Barons'' War. After John''s death, the regency government of his young son, Henry III, reissued the document in 1216, stripped of some of its more radical content, in an unsuccessful bid to build political support for their cause. At the end of the war in 1217, it formed part of the peace treaty agreed at Lambeth, where the document acquired the name "Magna Carta", to distinguish it from the smaller Charter of the Forest, which was issued at the same time. Short of funds, Henry reissued the charter again in 1225 in exchange for a grant of new taxes. His son, Edward I, repeated the exercise in 1297, this time confirming it as part of England''s statute law.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the charter''s creation and terms, then traces its annulment and reissues."}, {"id": "B", "text": "It compares English and French legal systems."}, {"id": "C", "text": "It lists the barons who fought in the First Barons'' War."}, {"id": "D", "text": "It explains how Magna Carta was translated into modern English."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Magna Carta", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Magna_Carta', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS006', 'A', ARRAY['A']::TEXT[], 'The passage is organized around the document''s origin, contents, failure, and eventual permanence.', '{"B": "The text moves from the sealing at Runnymede to the annulment and later confirmations.", "C": "French law is not discussed.", "D": "No barons are named individually."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE006', 'HDSAT-RW-M20-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Magna Carta (Medieval Latin for "Great Charter"), sometimes spelled Magna Charta, is a royal charter of rights sealed by King John of England at Runnymede, near Windsor, on 15 June 1215. First drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons who demanded that the King confirm the Charter of Liberties, it promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown, to be implemented through a council of 25 barons. Neither side stood by their commitments, and the charter was annulled by Pope Innocent III, leading to the First Barons'' War. After John''s death, the regency government of his young son, Henry III, reissued the document in 1216, stripped of some of its more radical content, in an unsuccessful bid to build political support for their cause. At the end of the war in 1217, it formed part of the peace treaty agreed at Lambeth, where the document acquired the name "Magna Carta", to distinguish it from the smaller Charter of the Forest, which was issued at the same time. Short of funds, Henry reissued the charter again in 1225 in exchange for a grant of new taxes. His son, Edward I, repeated the exercise in 1297, this time confirming it as part of England''s statute law.', 'Which quotation from the text most directly supports the claim that the charter promised fair legal treatment?', '[{"id": "A", "text": "First drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons who demanded that the King confirm the Charter of Liberties, it promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown, to be implemented through a council of 25 barons."}, {"id": "B", "text": "After John''s death, the regency government of his young son, Henry III, reissued the document in 1216, stripped of some of its more radical content."}, {"id": "C", "text": "His son, Edward I, repeated the exercise in 1297, this time confirming it as part of England''s statute law."}, {"id": "D", "text": "Magna Carta (Medieval Latin for \"Great Charter\"), sometimes spelled Magna Charta, is a royal charter of rights sealed by King John of England at Runnymede, near Windsor, on 15 June 1215."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Magna Carta", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Magna_Carta', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE006', 'A', ARRAY['A']::TEXT[], 'Only the correct quotation lists protection from illegal imprisonment and access to impartial justice.', '{"D": "This sentence identifies the document, its sealing date, and its location.", "B": "This sentence describes a later reissue.", "C": "This sentence describes confirmation as statute law."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI007', 'HDSAT-RW-M20-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Silk Road was a network of Asian trade routes active from the second century BCE until the mid-15th century. Spanning over 6,400 km (4,000 mi) on land, it played a central role in facilitating economic, cultural, political, and religious interactions between the Eastern and Western worlds. The name "Silk Road" was coined in the late 19th century, but some 20th- and 21st-century historians instead prefer the term Silk Routes, on the grounds that it more accurately describes the intricate web of land and sea routes connecting Central, East, South, Southeast, and West Asia as well as East Africa and Southern Europe. In fact, some scholars criticise or even dismiss the idea of silk roads and call for a new definition or alternate term. According to them, the literature using this term has "privileged the sedentary and literate empires at either end of Eurasia" thereby ignoring the contributions of steppe nomads. In addition, the classic definition sidelines prominent civilisations such as India and Iran. The Silk Road derives its name from the highly lucrative trade of silk textiles that were primarily produced in China. The network began with the expansion of the Han dynasty (202 BCE – 220 CE) into Central Asia around 114 BCE, through the missions and explorations of the Chinese imperial envoy Zhang Qian, which brought the region under unified control.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Silk Road carried only silk and no other goods."}, {"id": "B", "text": "The Silk Road was a long-lived web of trade routes whose name and scope historians continue to debate."}, {"id": "C", "text": "The Silk Road was a single road built by the Han dynasty."}, {"id": "D", "text": "The term Silk Road was used by merchants during the Han dynasty."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Silk Road", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Silk_Road', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI007', 'B', ARRAY['B']::TEXT[], 'The passage describes the network, explains its name, and presents scholarly criticism of the term.', '{"C": "The text calls it a network of routes, not a single road.", "D": "The text says the name was coined in the late 19th century.", "A": "The text says it facilitated economic, cultural, political, and religious interactions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF007', 'HDSAT-RW-M20-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Silk Road was a network of Asian trade routes active from the second century BCE until the mid-15th century. Spanning over 6,400 km (4,000 mi) on land, it played a central role in facilitating economic, cultural, political, and religious interactions between the Eastern and Western worlds. The name "Silk Road" was coined in the late 19th century, but some 20th- and 21st-century historians instead prefer the term Silk Routes, on the grounds that it more accurately describes the intricate web of land and sea routes connecting Central, East, South, Southeast, and West Asia as well as East Africa and Southern Europe. In fact, some scholars criticise or even dismiss the idea of silk roads and call for a new definition or alternate term. According to them, the literature using this term has "privileged the sedentary and literate empires at either end of Eurasia" thereby ignoring the contributions of steppe nomads. In addition, the classic definition sidelines prominent civilisations such as India and Iran. The Silk Road derives its name from the highly lucrative trade of silk textiles that were primarily produced in China. The network began with the expansion of the Han dynasty (202 BCE – 220 CE) into Central Asia around 114 BCE, through the missions and explorations of the Chinese imperial envoy Zhang Qian, which brought the region under unified control.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF007', 'A', ARRAY['A']::TEXT[], 'The term''s late coinage implies earlier traders did not call their routes by that name.', '{"C": "A name coined centuries later could not have been used by earlier traders.", "B": "The text says historians prefer Silk Routes; it does not say traders used that term.", "D": "The text describes interactions across Asia, Africa, and Europe."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS007', 'HDSAT-RW-M20-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Silk Road was a network of Asian trade routes active from the second century BCE until the mid-15th century. Spanning over 6,400 km (4,000 mi) on land, it played a central role in facilitating economic, cultural, political, and religious interactions between the Eastern and Western worlds. The name "Silk Road" was coined in the late 19th century, but some 20th- and 21st-century historians instead prefer the term Silk Routes, on the grounds that it more accurately describes the intricate web of land and sea routes connecting Central, East, South, Southeast, and West Asia as well as East Africa and Southern Europe. In fact, some scholars criticise or even dismiss the idea of silk roads and call for a new definition or alternate term. According to them, the literature using this term has "privileged the sedentary and literate empires at either end of Eurasia" thereby ignoring the contributions of steppe nomads. In addition, the classic definition sidelines prominent civilisations such as India and Iran. The Silk Road derives its name from the highly lucrative trade of silk textiles that were primarily produced in China. The network began with the expansion of the Han dynasty (202 BCE – 220 CE) into Central Asia around 114 BCE, through the missions and explorations of the Chinese imperial envoy Zhang Qian, which brought the region under unified control.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines the network, examines the name''s origin and critics'' objections, and explains how the network began."}, {"id": "B", "text": "It narrates a merchant''s journey from China to Rome."}, {"id": "C", "text": "It argues that the Silk Road never existed."}, {"id": "D", "text": "It compares silk production with cotton production."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Silk Road", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Silk_Road', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
