INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE008', 'HDSAT-RW-M20-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Library of Alexandria in Alexandria, Egypt, was one of the largest and most significant libraries of the ancient world. The library was part of a larger research institution called the Mouseion, which was dedicated to the Muses, the nine goddesses of the arts. The idea of the library in Alexandria may have been proposed by Demetrius of Phalerum, an exiled Athenian statesman living in Alexandria, to Ptolemy I Soter, who may have established plans for the library, but the library itself was probably not built until the reign of his son Ptolemy II Philadelphus. The library quickly acquired many papyrus scrolls, owing largely to the Ptolemaic kings'' aggressive and well-funded policies for procuring texts. It is unknown how many scrolls were housed at any given time at the Library of Alexandria, but estimates range from 40,000 to 700,000. Alexandria came to be regarded as the capital of knowledge and learning in part because of the Great Library.', 'Which quotation from the text most directly supports the claim that the Ptolemies spent heavily to obtain texts?', '[{"id": "A", "text": "The library quickly acquired many papyrus scrolls, owing largely to the Ptolemaic kings'' aggressive and well-funded policies for procuring texts."}, {"id": "B", "text": "Alexandria came to be regarded as the capital of knowledge and learning in part because of the Great Library."}, {"id": "C", "text": "The library was part of a larger research institution called the Mouseion, which was dedicated to the Muses."}, {"id": "D", "text": "The idea of the library in Alexandria may have been proposed by Demetrius of Phalerum."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Library of Alexandria", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Library_of_Alexandria', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE008', 'A', ARRAY['A']::TEXT[], 'The correct quotation directly names aggressive, well-funded procurement policies.', '{"C": "This sentence describes the Mouseion.", "D": "This sentence describes who may have proposed the library.", "B": "This sentence describes the city''s reputation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI009', 'HDSAT-RW-M20-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Erie Canal is a historic canal in upstate New York that runs east–west between the Hudson River and Lake Erie. Completed in 1825, the canal was the first navigable waterway connecting the Atlantic Ocean to the upper Great Lakes above Niagara Falls, vastly reducing the costs of transporting people and goods across the Appalachians. The Erie Canal accelerated the settlement of the Great Lakes region, the westward expansion of the United States, and the economic ascendancy of New York state. A canal from the Hudson River to the Great Lakes was first proposed in the 1780s, but a formal survey was not conducted until 1808. The New York State Legislature authorized construction in 1817. Political opponents of the canal, referring to its lead supporter New York Governor DeWitt Clinton, denigrated the project as "Clinton''s Folly" and "Clinton''s Big Ditch". The canal saw quick success upon opening on October 26, 1825, with toll revenue covering the state''s construction debt within the first year of operation. The westward connection gave New York City a strong advantage over all other US ports and brought major growth to canal cities such as Albany, Utica, Syracuse, Rochester, and Buffalo. The construction of the Erie Canal was a landmark civil engineering achievement in the early history of the United States. When built, the 363-mile (584 km) canal was the second-longest in the world after the Grand Canal in China.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The canal was built without any political opposition."}, {"id": "B", "text": "The Erie Canal was a failure that left New York in debt for decades."}, {"id": "C", "text": "The canal connected the Pacific Ocean to the Great Lakes."}, {"id": "D", "text": "The Erie Canal linked the Atlantic to the Great Lakes, cut transport costs, and spurred settlement and economic growth."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Erie Canal", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Erie_Canal', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI009', 'D', ARRAY['D']::TEXT[], 'The passage describes the canal''s route, construction, early success, and regional effects.', '{"B": "The text says toll revenue covered the construction debt within the first year.", "C": "The text says it connected the Atlantic Ocean to the upper Great Lakes.", "A": "The text describes opponents who called it Clinton''s Folly."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF009', 'HDSAT-RW-M20-INF009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Erie Canal is a historic canal in upstate New York that runs east–west between the Hudson River and Lake Erie. Completed in 1825, the canal was the first navigable waterway connecting the Atlantic Ocean to the upper Great Lakes above Niagara Falls, vastly reducing the costs of transporting people and goods across the Appalachians. The Erie Canal accelerated the settlement of the Great Lakes region, the westward expansion of the United States, and the economic ascendancy of New York state. A canal from the Hudson River to the Great Lakes was first proposed in the 1780s, but a formal survey was not conducted until 1808. The New York State Legislature authorized construction in 1817. Political opponents of the canal, referring to its lead supporter New York Governor DeWitt Clinton, denigrated the project as "Clinton''s Folly" and "Clinton''s Big Ditch". The canal saw quick success upon opening on October 26, 1825, with toll revenue covering the state''s construction debt within the first year of operation. The westward connection gave New York City a strong advantage over all other US ports and brought major growth to canal cities such as Albany, Utica, Syracuse, Rochester, and Buffalo. The construction of the Erie Canal was a landmark civil engineering achievement in the early history of the United States. When built, the 363-mile (584 km) canal was the second-longest in the world after the Grand Canal in China.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-INF009', 'B', ARRAY['B']::TEXT[], 'Debt repayment from first-year tolls is direct evidence of early financial success.', '{"D": "Covering the debt from tolls within a year indicates strong early revenue.", "C": "The text says revenue covered the debt, not that new taxes were needed.", "A": "Toll revenue implies substantial traffic."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-TS009', 'HDSAT-RW-M20-TS009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Erie Canal is a historic canal in upstate New York that runs east–west between the Hudson River and Lake Erie. Completed in 1825, the canal was the first navigable waterway connecting the Atlantic Ocean to the upper Great Lakes above Niagara Falls, vastly reducing the costs of transporting people and goods across the Appalachians. The Erie Canal accelerated the settlement of the Great Lakes region, the westward expansion of the United States, and the economic ascendancy of New York state. A canal from the Hudson River to the Great Lakes was first proposed in the 1780s, but a formal survey was not conducted until 1808. The New York State Legislature authorized construction in 1817. Political opponents of the canal, referring to its lead supporter New York Governor DeWitt Clinton, denigrated the project as "Clinton''s Folly" and "Clinton''s Big Ditch". The canal saw quick success upon opening on October 26, 1825, with toll revenue covering the state''s construction debt within the first year of operation. The westward connection gave New York City a strong advantage over all other US ports and brought major growth to canal cities such as Albany, Utica, Syracuse, Rochester, and Buffalo. The construction of the Erie Canal was a landmark civil engineering achievement in the early history of the United States. When built, the 363-mile (584 km) canal was the second-longest in the world after the Grand Canal in China.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the canal and its effects, then explains its origins, opposition, and engineering significance."}, {"id": "B", "text": "It compares the Erie Canal with the Grand Canal in detail."}, {"id": "C", "text": "It narrates a boat journey along the canal in the present tense."}, {"id": "D", "text": "It argues that canals were replaced by railroads before 1825."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Erie Canal", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Erie_Canal', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-TS009', 'A', ARRAY['A']::TEXT[], 'The passage opens with the canal''s significance, then supplies its history, opposition, and scale.', '{"C": "The text moves from the canal''s completion and impact to its planning and construction.", "B": "No journey is narrated.", "D": "The Grand Canal is mentioned only as longer."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CE009', 'HDSAT-RW-M20-CE009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Erie Canal is a historic canal in upstate New York that runs east–west between the Hudson River and Lake Erie. Completed in 1825, the canal was the first navigable waterway connecting the Atlantic Ocean to the upper Great Lakes above Niagara Falls, vastly reducing the costs of transporting people and goods across the Appalachians. The Erie Canal accelerated the settlement of the Great Lakes region, the westward expansion of the United States, and the economic ascendancy of New York state. A canal from the Hudson River to the Great Lakes was first proposed in the 1780s, but a formal survey was not conducted until 1808. The New York State Legislature authorized construction in 1817. Political opponents of the canal, referring to its lead supporter New York Governor DeWitt Clinton, denigrated the project as "Clinton''s Folly" and "Clinton''s Big Ditch". The canal saw quick success upon opening on October 26, 1825, with toll revenue covering the state''s construction debt within the first year of operation. The westward connection gave New York City a strong advantage over all other US ports and brought major growth to canal cities such as Albany, Utica, Syracuse, Rochester, and Buffalo. The construction of the Erie Canal was a landmark civil engineering achievement in the early history of the United States. When built, the 363-mile (584 km) canal was the second-longest in the world after the Grand Canal in China.', 'Which quotation from the text most directly supports the claim that the canal sharply lowered transport costs?', '[{"id": "A", "text": "Completed in 1825, the canal was the first navigable waterway connecting the Atlantic Ocean to the upper Great Lakes above Niagara Falls, vastly reducing the costs of transporting people and goods across the Appalachians."}, {"id": "B", "text": "The westward connection gave New York City a strong advantage over all other US ports."}, {"id": "C", "text": "The New York State Legislature authorized construction in 1817."}, {"id": "D", "text": "The Erie Canal is a historic canal in upstate New York that runs east-west between the Hudson River and Lake Erie."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Erie Canal", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Erie_Canal', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CE009', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly says the canal vastly reduced transport costs.', '{"D": "This sentence describes the canal''s route.", "C": "This sentence gives the date of authorization.", "B": "This sentence describes New York City''s advantage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-CI010', 'HDSAT-RW-M20-CI010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Great Migration, sometimes known as the Great Northward Migration or the Black Migration, was the movement of six million Black Americans out of the rural Southern United States to the urban Northeast, Midwest, and West between 1910 and 1970. It was substantially driven by poor economic and social conditions due to prevalent racial segregation and discrimination in the Southern states where Jim Crow laws were upheld. In particular, continued lynchings motivated a portion of the migrants, as Black Americans searched for social reprieve. The historic change brought by the migration was amplified because the migrants, for the most part, moved to the then-largest cities in the United States (New York City, Chicago, Los Angeles, San Francisco, Philadelphia, Detroit, Cleveland, and Washington, D.C.) at a time when those cities had a central cultural, social, political, and economic influence over the United States; there, Black Americans established culturally influential communities of their own. From the earliest U.S. population statistics in 1780 until 1910, more than 90% of the Black-American population lived in the American South, making up the majority of the population in three Southern states: Louisiana (until about 1890), South Carolina (until the 1920s), and Mississippi (until the 1930s). But by the end of the Great Migration, just over half of the Black-American population lived in the South, while a little less than half lived in the North and West.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Great Migration moved Black Americans from Northern cities to the rural South."}, {"id": "B", "text": "The migration was caused mainly by a decline in Southern agriculture."}, {"id": "C", "text": "The migration involved only a few thousand people."}, {"id": "D", "text": "Millions of Black Americans left the rural South for Northern and Western cities, driven by discrimination and seeking better conditions."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Great Migration (African American)", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Great_Migration_(African_American)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M20-CI010', 'D', ARRAY['D']::TEXT[], 'The passage describes the migration''s scale, direction, causes, and demographic effects.', '{"A": "The text describes movement out of the rural South to the urban Northeast, Midwest, and West.", "C": "The text says six million people moved.", "B": "The text emphasizes segregation, discrimination, and lynching as drivers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M20-INF010', 'HDSAT-RW-M20-INF010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Great Migration, sometimes known as the Great Northward Migration or the Black Migration, was the movement of six million Black Americans out of the rural Southern United States to the urban Northeast, Midwest, and West between 1910 and 1970. It was substantially driven by poor economic and social conditions due to prevalent racial segregation and discrimination in the Southern states where Jim Crow laws were upheld. In particular, continued lynchings motivated a portion of the migrants, as Black Americans searched for social reprieve. The historic change brought by the migration was amplified because the migrants, for the most part, moved to the then-largest cities in the United States (New York City, Chicago, Los Angeles, San Francisco, Philadelphia, Detroit, Cleveland, and Washington, D.C.) at a time when those cities had a central cultural, social, political, and economic influence over the United States; there, Black Americans established culturally influential communities of their own. From the earliest U.S. population statistics in 1780 until 1910, more than 90% of the Black-American population lived in the American South, making up the majority of the population in three Southern states: Louisiana (until about 1890), South Carolina (until the 1920s), and Mississippi (until the 1930s). But by the end of the Great Migration, just over half of the Black-American population lived in the South, while a little less than half lived in the North and West.
