acial violence contributed to the migration?', '[{"id": "A", "text": "In particular, continued lynchings motivated a portion of the migrants, as Black Americans searched for social reprieve."}, {"id": "B", "text": "The Great Migration, sometimes known as the Great Northward Migration or the Black Migration, was the movement of six million Black Americans out of the rural Southern United States."}, {"id": "C", "text": "The historic change brought by the migration was amplified because the migrants, for the most part, moved to the then-largest cities in the United States."}, {"id": "D", "text": "But by the end of the Great Migration, just over half of the Black-American population lived in the South."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Great Migration (African American)", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Great_Migration_(African_American)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
